CREATE TABLE scheduled_jobs (id varchar(64) PRIMARY KEY,code varchar(128) NOT NULL,name text NOT NULL,description text NOT NULL,cron_spec varchar(256) NOT NULL,timezone varchar(128) NOT NULL,handler varchar(128) NOT NULL,timeout_seconds bigint NOT NULL,lock_ttl_seconds bigint NOT NULL,status varchar(32) NOT NULL,payload json NOT NULL,created_at timestamp(6) NOT NULL,created_by text NOT NULL,updated_at timestamp(6) NOT NULL,updated_by text NOT NULL,version bigint NOT NULL,deleted_at timestamp(6) NULL,deleted_by text,UNIQUE KEY scheduled_jobs_code_unique(code),KEY scheduled_jobs_page_idx(status,handler,code,id));
CREATE TRIGGER scheduled_jobs_audit_bi BEFORE INSERT ON scheduled_jobs FOR EACH ROW SET NEW.created_at=CURRENT_TIMESTAMP(6),NEW.created_by=NULLIF(TRIM(@app_actor_id),''),NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL ELSE NULLIF(TRIM(@app_actor_id),'') END;
CREATE TRIGGER scheduled_jobs_audit_bu BEFORE UPDATE ON scheduled_jobs FOR EACH ROW SET NEW.created_at=OLD.created_at,NEW.created_by=OLD.created_by,NEW.updated_at=CURRENT_TIMESTAMP(6),NEW.updated_by=NULLIF(TRIM(@app_actor_id),''),NEW.version=OLD.version+1,NEW.deleted_by=CASE WHEN NEW.deleted_at IS NULL THEN NULL WHEN OLD.deleted_at IS NULL THEN NULLIF(TRIM(@app_actor_id),'') ELSE OLD.deleted_by END;
CREATE TRIGGER scheduled_jobs_audit_bd BEFORE DELETE ON scheduled_jobs FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='physical delete is forbidden';
